def transform(grid):
    bg=max(set(x for row in grid for x in row),key=lambda x:sum(v==x for row in grid for v in row))
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col: seen.add((yy,xx)); q.append((yy,xx))
        if len(comp)>=2: comps.append((col,comp))
    for col,comp in comps:
      for r,c in comp: out[r][c]=col
      if len(comp)>=4:
        r0=min(r for r,c in comp); r1=max(r for r,c in comp); c0=min(c for r,c in comp); c1=max(c for r,c in comp)
        area=(r1-r0+1)*(c1-c0+1)
        if area-len(comp)<=2 and area<=100:
          for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=col
    return out
